    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        String[] tok = first.trim().isEmpty() ? new String[0] : first.trim().split("\\s+");
        TreeNode root = null;
        if (tok.length > 0 && !tok[0].equals("null")) {
            root = new TreeNode(Long.parseLong(tok[0]));
            ArrayDeque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            int i = 1;
            while (!queue.isEmpty() && i < tok.length) {
                TreeNode node = queue.poll();
                if (i < tok.length) {
                    if (!tok[i].equals("null")) {
                        node.left = new TreeNode(Long.parseLong(tok[i]));
                        queue.add(node.left);
                    }
                    i++;
                }
                if (i < tok.length) {
                    if (!tok[i].equals("null")) {
                        node.right = new TreeNode(Long.parseLong(tok[i]));
                        queue.add(node.right);
                    }
                    i++;
                }
            }
        }
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int q = Integer.parseInt(st.nextToken());
        long[] queries = new long[q];
        for (int i = 0; i < q; i++) queries[i] = Long.parseLong(st.nextToken());
        int[] res = getRanks(root, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
